// Story strings (workstream G, v0.4): comic pages, pops, Mom's calls, captions, SFX and UI labels. TR is the VO
// language; EN is a translation. Line format: id: [speakerKey, TR, EN]. Lines <= 90 chars. Merged into P.STR / P.LINES.
// Id scheme: L01s/L01m (level start/mid, levels 1-20), H05p1..H20p4 (hood pools, levels 21-100), H01b..H20b (boss pops),
// C05a.. (Mom's calls), H01i1a.. (hood intro pages), O1/E5/K20/E30/CMP/FN (story pages). Canon: narrative.md, journey.md.
(function () {
  Object.assign(P.STR.tr, {
    'spk.kaan': 'Kaan', 'spk.mila': 'Mila', 'spk.baba': 'Baba', 'spk.ahmet': 'Ahmet Abi', 'spk.stranger': 'Yabancı',
    'spk.shopkeeper': 'Esnaf', 'spk.zombie': 'Zombi', 'spk.cap': 'Anlatıcı',
    'spk.b.istiklal': 'Vatman', 'spk.b.galata': 'Tur Rehberi', 'spk.b.karakoy': 'Gelin', 'spk.b.bridge': 'Koca Balıkçı',
    'spk.b.eminonu': 'Kaptan', 'spk.b.sirkeci': 'Biletçi', 'spk.b.kapalicarsi': 'Halı Golem', 'spk.b.beyazit': 'Güvercinci',
    'spk.b.laleli': 'Toptancı', 'spk.b.aksaray': 'Dolmuşçu', 'spk.b.kumkapi': 'Balık Hamalı', 'spk.b.yenikapi': 'Akşam Kalabalığı',
    'spk.b.samatya': 'Mangal Baba', 'spk.b.yedikule': 'Anahtarcı', 'spk.b.zeytinburnu': 'Boyacı Ustası', 'spk.b.kazlicesme': 'Hortumcu',
    'spk.b.bakirkoy': 'Müdür', 'spk.b.bakirkoysahil': 'Dondurmacı', 'spk.b.atakoysahil': 'Yat Sahibi', 'spk.b.atakoy': 'Ahmet Abi',
    'cm.tap': 'Devam için dokun', 'cm.page.label': 'Çizgi roman sayfası', 'cm.tag.story': 'HİKÂYE', 'cm.tag.l1': 'İLK LOKMA',
    'cm.nosig': 'Sinyal yok', 'cm.sfx.cat': 'ÇAT!', 'cm.sfx.buzz': 'BZZT', 'cm.sfx.tik': 'TIK TIK', 'cm.sfx.kut': 'KÜT!',
    'cm.sfx.sak': 'ŞAK!', 'cm.sfx.sangir': 'ŞANGIR!', 'cm.sfx.bum': 'BUM!', 'cm.sfx.vin': 'VIIIN!',
  });
  Object.assign(P.STR.en, {
    'spk.kaan': 'Kaan', 'spk.mila': 'Mila', 'spk.baba': 'Dad', 'spk.ahmet': 'Ahmet Abi', 'spk.stranger': 'Stranger',
    'spk.shopkeeper': 'Shopkeeper', 'spk.zombie': 'Zombie', 'spk.cap': 'Narrator',
    'spk.b.istiklal': 'The Vatman', 'spk.b.galata': 'Tour Guide', 'spk.b.karakoy': 'The Bride', 'spk.b.bridge': 'Big Fisherman',
    'spk.b.eminonu': 'The Captain', 'spk.b.sirkeci': 'The Ticket Man', 'spk.b.kapalicarsi': 'The Carpet Golem',
    'spk.b.beyazit': 'The Pigeon Man', 'spk.b.laleli': 'The Wholesaler', 'spk.b.aksaray': 'The Dolmuş Driver',
    'spk.b.kumkapi': 'The Fish Porter', 'spk.b.yenikapi': 'The Evening Crowd', 'spk.b.samatya': 'The Grill Man',
    'spk.b.yedikule': 'The Key Keeper', 'spk.b.zeytinburnu': 'The Dye Foreman', 'spk.b.kazlicesme': 'The Hose Man',
    'spk.b.bakirkoy': 'The Principal', 'spk.b.bakirkoysahil': 'The Ice-Cream Man', 'spk.b.atakoysahil': 'The Yacht Owner',
    'spk.b.atakoy': 'Ahmet Abi',
    'cm.tap': 'Tap to continue', 'cm.page.label': 'Comic page', 'cm.tag.story': 'STORY', 'cm.tag.l1': 'FIRST BITE',
    'cm.nosig': 'No signal', 'cm.sfx.cat': 'THWACK!', 'cm.sfx.buzz': 'BZZT', 'cm.sfx.tik': 'TICK TICK', 'cm.sfx.kut': 'THUD!',
    'cm.sfx.sak': 'SNAP!', 'cm.sfx.sangir': 'CLANG!', 'cm.sfx.bum': 'BOOM!', 'cm.sfx.vin': 'VWOOSH!',
  });
  Object.assign(P.LINES, {
    // L1 outro (page O1). The L1 phone lines exit1/exit2 are reused on the phone panel.
    O1a: ['spk.cap', 'Akşam altı buçuk. İstiklal\'in ortasında, tramvay hattında.', 'Half six in the evening. Mid-İstiklal, on the tram line.'],
    O1b: ['spk.arda', 'Anne\'ye söz verdim. Eve geliyorum.', "I promised Mom. I'm coming home."],
    O1c: ['spk.arda', 'Tünel, Karaköy, köprü, Eminönü... Sonra sahil boyunca. Ataköy.', 'Tünel, Karaköy, the bridge, Eminönü... then along the shore. Ataköy.'],
    O1d: ['spk.arda', 'Kural üç neydi? Durma. Hiç durma.', 'Rule three? Don\'t stop. Not once.'],
    O1e: ['spk.cap', 'Ataköy: 17 km. Yürüyorum.', 'Ataköy: 17 km. Walking.'],
    // Hood intros (page hood_<id>, 3 panels each).
    H01i1a: ['spk.cap', 'Lezzet\'in camından çıktım. Dürümün tadı hâlâ ağzımda.', 'Just left the dürüm counter. The taste is still in my mouth.'],
    H01i1b: ['spk.usta', 'Afiyet olsun, genç! Bıçağı sıkma, ağırlığına bırak.', "Enjoy, young man! Don't squeeze the knife. Let its weight do it."],
    H01i2a: ['spk.cap', 'Yürüyenler, koşanlar. Rögarın altından sürünenler de var.', 'Walkers, runners. Crawlers under the manholes, too.'],
    H01i3a: ['spk.arda', 'Tamam. Kural bir: kafaya. Yürüyoruz.', 'Okay. Rule one: the head. Let\'s walk.'],
    H01i3b: ['spk.cap', 'Ataköy\'e 17 km. Hesap yapmayı bırakıyorum.', 'Ataköy is 17 km away. I\'m done doing the math.'],
    H02i1a: ['spk.cap', 'Galata\'nın taş merdivenleri. Fenerler yanıyor, kimse yok.', 'Galata\'s stone stairs. Lanterns still lit. Nobody here.'],
    H02i1b: ['spk.stranger', 'Son parçam bu. Sonra siz de gidin, olur mu?', 'This is my last tune. Then you go too, alright?'],
    H02i2a: ['spk.cap', 'Merdivenin dibinde bir tükürükçü. Asidi yere sıçratıyor.', 'A spitter at the foot of the stairs. It spits acid across the ground.'],
    H02i3a: ['spk.arda', 'Rehber hâlâ konuşuyor. Kimse dinlemiyor ama.', 'The tour guide is still talking. Nobody\'s listening, though.'],
    H02i3b: ['spk.cap', 'Galata. 1,8 km yol bitti.', 'Galata. 1.8 km done.'],
    H03i1a: ['spk.cap', 'Karaköy. Düğün kafesi kapanmış. Pastalar hâlâ camın arkasında.', 'Karaköy. The wedding café is shut. The cakes are still behind the glass.'],
    H03i1b: ['spk.arda', 'Bir dilim alabilir miydim şimdi? Yok. Sakin ol, Arda.', 'Could I take a slice right now? No. Calm down, Arda.'],
    H03i2a: ['spk.cap', 'Paşa, sokağın kedisi. Ürkmez, sadece bakar.', 'Paşa, the street cat. Doesn\'t scare. Just watches.'],
    H03i2b: ['spk.arda', 'Bu kedi bizi takip ediyor galiba.', 'I think this cat is following us.'],
    H03i3a: ['spk.cap', 'Şişkinler gaz tüplerinin yanında. Biri patlarsa zincir olur.', 'Bloaters by the gas tanks. One pops, and it\'s a chain reaction.'],
    H04i1a: ['spk.cap', 'Galata Köprüsü. İki kat: üstte olta ipleri, altta balık lokantaları.', 'Galata Bridge. Two decks: fishing lines on top, fish restaurants below.'],
    H04i2a: ['spk.kaan', 'Yaklaşma! Sen... enfekte misin?', 'Stay back! Are you... infected?'],
    H04i3a: ['spk.arda', 'Tamam abi, sakin ol. Ben de insanım.', 'Easy, bro. I\'m human too.'],
    H04i3b: ['spk.cap', 'Olta ipleri ayağa dolanıyor. Sis yükseliyor.', 'Fishing lines are tangling my feet. Fog is rising.'],
    H05i1a: ['spk.cap', 'Eminönü. Baharat çuvalları, tuzlu hava, balık-ekmek tekneleri.', 'Eminönü. Spice sacks, salty air, the fish-sandwich boats.'],
    H05i2a: ['spk.kaan', 'Kaptanımın teknesi burada bağlıydı. Gel, bakalım.', 'My captain\'s boat was moored here. Come on, let\'s look.'],
    H05i3a: ['spk.cap', 'Kaptan dönmüş. Kaan bunu henüz bilmiyor.', 'The captain has turned. Kaan doesn\'t know yet.'],
    H05i3b: ['spk.arda', 'Kaan, arkana bak!', 'Kaan, behind you!'],
    H06i1a: ['spk.cap', 'Sirkeci. Kocaman saat hâlâ çalışıyor. Ya da çalışıyormuş gibi.', 'Sirkeci. The huge clock still ticks. Or looks like it does.'],
    H06i2a: ['spk.kaan', 'Turnikeler kapalı. Bu kapıyı açacak bir şey lazım.', 'The turnstiles are shut. We need something to open this gate.'],
    H06i3a: ['spk.cap', 'Biletçi kapıların arkasında. Önünde bir sıra zombi.', 'The Ticket Man is behind the gates. A queue of zombies in front.'],
    H06i3b: ['spk.arda', 'Ben o sıraya girmem.', 'I\'m not joining that queue.'],
    H07i1a: ['spk.cap', 'Kapalıçarşı. Kemerlerin altında sıcak lambalar, duvarda kilimler.', 'Kapalıçarşı. Warm lamps under the vaults, kilims on the walls.'],
    H07i2a: ['spk.cap', 'Kepenkte el yazısı: \'Kapıyı açmayın.\'', 'A handwritten sign on a shutter: \'Do not open the door.\''],
    H07i3a: ['spk.kaan', 'Biri buraya girmiş. Ya da içeride hâlâ biri var.', 'Someone was in here. Or someone still is.'],
    H07i3b: ['spk.cap', 'Artık tehlike zombilerden ibaret değil.', 'Now the danger isn\'t only the zombies.'],
    H08i1a: ['spk.cap', 'Beyazıt meydanı. Kitapçı tezgâhları, güvercinler, bir \'Bugün kapalı\' tabelası.', 'Beyazıt square. Bookstalls, pigeons, a \'Closed today\' sign.'],
    H08i2a: ['spk.arda', 'Güvercinler birden kalktı. Bir şey yaklaşıyor demek.', 'The pigeons took off all at once. Something\'s coming.'],
    H08i3a: ['spk.cap', 'Güvercinci her sabah kuş beslerdi. Şimdi kuşlar onu bekliyor.', 'The Pigeon Man used to feed the birds every morning. Now they wait for him.'],
    H09i1a: ['spk.cap', 'Laleli. Vitrinler dolu. Mankenlerin hepsi bize bakıyor.', 'Laleli. The windows are full. The mannequins are all looking at us.'],
    H09i2a: ['spk.kaan', 'Bunlar zombi mi? Yoksa sadece manken mi?', 'Are they zombies? Or just mannequins?'],
    H09i2b: ['spk.arda', 'Bilmiyorum. Üç metreye yaklaşmayalım.', 'No idea. Let\'s not get within three metres.'],
    H09i3a: ['spk.arda', 'Kıpırdadı! Hepsi kıpırdadı!', 'It moved! They all moved!'],
    H10i1a: ['spk.cap', 'Aksaray. Dolmuşlar yolda kalmış, farları hâlâ yanıyor.', 'Aksaray. The minibuses are stuck on the road, headlights still on.'],
    H10i2a: ['spk.arda', 'Bir korna sesi... Bir dolmuş geliyor.', 'A horn... A minibus is coming.'],
    H10i3a: ['spk.cap', 'Dolmuşçu direksiyonda. Kapısı açık, içi karanlık.', 'The Dolmuş Driver is at the wheel. Door open, dark inside.'],
    H11i1a: ['spk.cap', 'Kumkapı. Balık sandıkları buzda. Her yerde deniz kokusu.', 'Kumkapı. Fish crates on ice. The smell of the sea everywhere.'],
    H11i2a: ['spk.kaan', 'Burada bir mezeci vardı. Her yaz gelirdim.', 'There used to be a meze place here. I came every summer.'],
    H11i3a: ['spk.cap', 'Bir zombi müzisyen aynı parçayı çalıyor. Bitmiyor.', 'A zombie musician plays the same tune. It never ends.'],
    H12i1a: ['spk.cap', 'Yenikapı. Metro tünelleri. Işık sadece el fenerinden.', 'Yenikapı. The metro tunnels. Light only from the torch.'],
    H12i2a: ['spk.cap', 'Son mesaj, dünden: \'Eve gel. Seni bekliyoruz.\'', 'Last message, from yesterday: \'Come home. We\'re waiting for you.\''],
    H12i3a: ['spk.arda', 'Merdivenden iniyorlar. Sesleri duyuyorum.', 'They\'re coming down the stairs. I can hear them.'],
    H13i1a: ['spk.cap', 'Samatya. Şafak. Yerde battaniyeler, deniz mavi.', 'Samatya. Dawn. Blankets on the ground, the sea blue.'],
    H13i2a: ['spk.news', '...güvenli bölgelere gidin. Kuzeydeki ormandan uzak durun.', '...go to the safe zones. Stay away from the forest up north.'],
    H13i3a: ['spk.arda', 'Güvenli bölge? Hangi taraf güvenli?', 'Safe zone? Which way is safe?'],
    H14i1a: ['spk.cap', 'Yedikule surları. Eski kuleler, sarmaşıklar. Sur bir kez tutmuştu.', 'Yedikule walls. Old towers, ivy. The walls held once before.'],
    H14i2a: ['spk.kaan', 'Anahtarcı kapıları kilitlemiş. Anahtarlar onda.', 'The Key Keeper locked the gates. The keys are on him.'],
    H14i3a: ['spk.cap', 'Anahtarcının halkası her adımda şıngırdıyor.', 'The Key Keeper\'s key ring jingles with every step.'],
    H15i1a: ['spk.cap', 'Zeytinburnu. Boya atölyeleri. Renk renk bidonlar, hepsi dolu.', 'Zeytinburnu. Dye workshops. Drums in every colour, all full.'],
    H15i2a: ['spk.kaan', 'Boyacı Ustası vardiyasını bitirmemiş. Hâlâ çalışıyor.', 'The Dye Foreman never finished his shift. He\'s still working.'],
    H15i3a: ['spk.cap', 'Bidonlar üst üste. Bir kıvılcım, bir zincir.', 'Drums stacked to the top. One spark, one chain.'],
    H16i1a: ['spk.cap', 'Kazlıçeşme. Serin sabah, yeşil çimler. Fıskiyeler dönüyor.', 'Kazlıçeşme. A cool morning, green lawns. Sprinklers turning.'],
    H16i2a: ['spk.arda', 'Bu kadar sakin olması iyi değil.', 'Being this calm isn\'t a good sign.'],
    H16i3a: ['spk.cap', 'Hortumcu asidi uzun hatlarla püskürtüyor, sonra birikintiler kalıyor.', 'The Hose Man sprays acid in long lines, then leaves puddles behind.'],
    H17i1a: ['spk.cap', 'Bakırköy Çarşısı. Tavan camından toz sütunları iniyor.', 'Bakırköy Bazaar. Dust columns fall through the skylight.'],
    H17i2a: ['spk.arda', 'Eski lisemin yanındayız. Dolabım hâlâ orada mı acaba?', 'We\'re right by my old high school. I wonder if my locker is still there.'],
    H17i3a: ['spk.cap', 'Müdür megafonu açtı. Okul zili çalınca dalga gelir.', 'The Principal has his megaphone on. When the school bell rings, a wave comes.'],
    H18i1a: ['spk.cap', 'Bakırköy sahili. Palmiyeler, bisiklet yolu, bir dondurmacı arabası.', 'Bakırköy shore. Palms, a bike lane, an ice-cream cart.'],
    H18i2a: ['spk.arda', 'Bir keresinde bana bedava dondurma vermişti.', 'He once gave me a free ice cream.'],
    H18i3a: ['spk.cap', 'Arabanın çanı çalıyor. Her çalışta yeni bir dalga.', 'The cart\'s bell is ringing. With every chime, another wave.'],
    H19i1a: ['spk.cap', 'Ataköy Marina. Direkler arasında gün doğuyor. Eve bir kilometre.', 'Ataköy Marina. The sun rises between the masts. One kilometre to home.'],
    H19i2a: ['spk.kaan', 'Mahalleni biliyorum dediğin. Hadi, göster.', 'You said you know this neighbourhood. Go on, show me.'],
    H19i2b: ['spk.arda', 'Ahmet Abi\'nin ekmeği burada. Göreceksin.', 'Ahmet Abi\'s bread is here. You\'ll see.'],
    H19i3a: ['spk.cap', 'Yat sahibi. Rıhtımda zincir sallanıyor. Denizciler çıkıyor.', 'The Yacht Owner. The dock chain swings. Sailors crawl out.'],
    H20i1a: ['spk.cap', 'Ataköy. Bej binalar, mavi panjurlar, balkonlarda çamaşır ipleri.', 'Ataköy. Beige blocks, blue shutters, laundry on the balconies.'],
    H20i2a: ['spk.arda', 'Fırın kokusu... Ahmet Abi her sabah buradaydı.', 'The bakery smell... Ahmet Abi was always here, every morning.'],
    H20i3a: ['spk.cap', 'Kapıcı kulübesinde biri var. Kapı aralık.', 'Someone\'s in the porter\'s booth. The door is ajar.'],
  });
})();

// Generated-id groups (boss, level, pool, call, page lines) are merged below in their own scope.
(function () {
// Boss pops: one per hood (stage 5). The boss speaks; the portrait is 'zombie' (Ahmet Abi: 'shopkeeper').
function bossLines() {
  return {
    H01b: ['spk.b.istiklal', 'Hat kapalı! Tramvay buradan geçiyor!', 'Line\'s closed! The tram goes through here!'],
    H02b: ['spk.b.galata', 'Herkes bana baksın! Bayrağı takip edin!', 'Everyone look at me! Follow the flag!'],
    H03b: ['spk.b.karakoy', 'Buketi atıyorum! Kim yakalarsa onun!', 'Throwing the bouquet! Whoever catches it!'],
    H04b: ['spk.b.bridge', 'Olta attım! Çekiyorum, çekiyorum!', 'Line\'s out! Reeling, reeling!'],
    H05b: ['spk.b.eminonu', 'Zincir hazır! Hepiniz tekneye! Yemek vakti!', 'Chain\'s ready! All aboard! Dinner\'s served!'],
    H06b: ['spk.b.sirkeci', 'Bilet yok, giriş yok!', 'No ticket, no entry!'],
    H07b: ['spk.b.kapalicarsi', 'Halılar sarılı, içi dolu. Açarsan bedelini ödersin.', 'The carpets are rolled tight and stuffed. Open one and you pay.'],
    H08b: ['spk.b.beyazit', 'Yemim var! Gelin, gelin!', 'I\'ve got feed! Come on, come on!'],
    H09b: ['spk.b.laleli', 'Hepsi toptan, hepsi benim!', 'It\'s all wholesale, and it\'s all mine!'],
    H10b: ['spk.b.aksaray', 'Kapı kapanmadan kalk abi!', 'Get in before the door shuts, bro!'],
    H11b: ['spk.b.kumkapi', 'Sandığı kaldırdım, şimdi seni kaldırırım!', 'I lifted the crate, now I\'ll lift you!'],
    H12b: ['spk.b.yenikapi', 'Yetişin! Tren gidiyor!', 'Hurry! The train\'s leaving!'],
    H13b: ['spk.b.samatya', 'Közler hazır! Sıra sende!', 'The embers are ready! Your turn!'],
    H14b: ['spk.b.yedikule', 'Bu kapının anahtarı bende!', 'The key to this gate is mine!'],
    H15b: ['spk.b.zeytinburnu', 'Vardiya bitmedi! Bidonları boşaltın!', 'The shift isn\'t over! Empty those drums!'],
    H16b: ['spk.b.kazlicesme', 'Su bitmez, asit bitmez!', 'The water never stops, the acid never stops!'],
    H17b: ['spk.b.bakirkoy', 'Zil çaldı! Herkes sınıfa!', 'The bell\'s rung! Everybody to class!'],
    H18b: ['spk.b.bakirkoysahil', 'Bir kaşık daha? Bedava, bedava!', 'One more scoop? Free, free!'],
    H19b: ['spk.b.atakoysahil', 'Bu rıhtım benim! Herkesi bağlarım!', 'This dock is mine! I\'ll tie up everyone!'],
    H20b: ['spk.b.atakoy', 'Ekmek al, yavrum. Sonra beni affedersin.', 'Take some bread, my boy. Then forgive me.'],
  };
}

// Level pops for levels 1-20 (start and mid). L05s and L15s are Mom's calls (see callLines).
function levelLines() {
  return {
    L01s: ['spk.arda', 'Kural bir: kafaya. Kural iki: asla ısırılma.', 'Rule one: the head. Rule two: never get bitten.'],
    L01m: ['spk.arda', 'Kural üç... Hatırladım. DURMA.', 'Rule three... I remember. DON\'T STOP.'],
    L02s: ['spk.arda', 'Çekmiyor. Anne\'ye bir kez daha deneyeyim.', 'No signal. Let me try Mom once more.'],
    L02m: ['spk.usta', 'Acele eden dürümü yakar. Bugün yakmayacağım.', 'Hurry and you burn the wrap. Not today.'],
    L03s: ['spk.arda', 'Kestaneci arabasını bize sürüyor! Arabayı kurtar!', 'The chestnut vendor is driving his cart at us! Save the cart!'],
    L03m: ['spk.arda', 'Kestaneler kızardı. Bir tane de bana.', 'The chestnuts are roasted. One for me too.'],
    L04s: ['spk.arda', 'Tramvay teli koptu. Kıvılcım yağıyor!', 'The tram wire snapped. Sparks are raining down!'],
    L04m: ['spk.arda', 'Teli kes, ama üstüne basma. Elektrik kötü.', 'Cut the wire, but don\'t step on it. Electricity is bad.'],
    L05m: ['spk.arda', 'Vatman kabinden çıkıyor. Tramvay hattı burada bitiyor.', 'The Vatman is out of the cab. The tram line ends here.'],
    L06s: ['spk.arda','Galata\'dan aşağı iniyoruz. Taş merdivenler kaygan.', 'Going down Galata. The stone steps are slippery.'],
    L06m: ['spk.arda', 'Basamaklar dar. Sıkışırsan kenara geç.', 'The steps are narrow. If you get stuck, step aside.'],
    L07s: ['spk.arda', 'Tükürükçü! Asit yere sıçradı, dikkat!', 'Spitter! Acid splashed on the ground, watch out!'],
    L07m: ['spk.arda', 'Asit birikintisi yavaşlatıyor. Kaymıyorsun ama yavaşlıyorsun.', 'Acid puddles slow you down. No slipping, but you do slow.'],
    L08s: ['spk.arda', 'Rehber bayrağını sallıyor. Bayrakçıyı önce vur!', 'The guide is waving a flag. Take out the flag bearer first!'],
    L08m: ['spk.arda', 'Bayrak düşünce grup yavaşlıyor. Bayrağa odaklan.', 'When the flag drops, the group slows down. Focus on the flag.'],
    L09s: ['spk.arda', 'Merdivenden sel gibi iniyorlar!', 'They\'re pouring down the stairs like a flood!'],
    L09m: ['spk.arda', 'Basamakta dur, sırayla gelsinler. Sıkışma yok.', 'Hold the step, let them come in turns. No crowding.'],
    L10s: ['spk.arda', 'Rehberin sesi duyuluyor. Son adım bu.', 'I can hear the guide. This is the last step.'],
    L10m: ['spk.arda', 'Megafon çalıyor. Bayrak onu koruyor. Bayrağı kır.', 'The megaphone\'s blaring. The flag protects him. Break the flag.'],
    L11s: ['spk.arda', 'Karaköy\'e iniyoruz. Yokuş dik, dizim zorluyor.', 'We\'re heading down to Karaköy. The slope is steep, my knees complain.'],
    L11m: ['spk.arda', 'Bu sokaklarda kimse yok. Yalnız bir kedi var.', 'Nobody on these streets. Just a cat.'],
    L12s: ['spk.arda', 'Bir kedi bizi takip ediyor. Adı Paşa olsun.', 'A cat\'s following us. Let\'s call him Paşa.'],
    L12m: ['spk.arda', 'Paşa tıslıyor. Bir şey var, ne olduğunu bilmiyorum.', 'Paşa is hissing. Something\'s there, I just don\'t know what.'],
    L13s: ['spk.arda', 'Korna sesi. Düğün konvoyu geliyor galiba.', 'Horns. A wedding convoy must be coming.'],
    L13m: ['spk.arda', 'Düğün mü? Bu saatte, bu sokakta mı?', 'A wedding? At this hour, on this street?'],
    L14s: ['spk.arda', 'Paşa yine tıslıyor. Boş sokak diyorum, boş değil.', 'Paşa\'s hissing again. I said the alley\'s empty. It isn\'t.'],
    L14m: ['spk.arda', 'Duvarın arkası dolu. Sakin ol, sayıyorum: üç, dört...', 'Behind that wall it\'s full. Stay calm, I\'m counting: three, four...'],
    L15m: ['spk.arda', 'Gelin buketi kaldırdı. Yakalamadan kaç!', 'The bride lifted the bouquet. Get away before you catch it!'],
    L16s: ['spk.arda','Köprü! İki katlı... Altta balık lokantası var.', 'The bridge! Two decks... fish restaurants below.'],
    L16m: ['spk.arda', 'Havai fişek! Konvoydan düşmüş. Lazım olur.', 'Fireworks! Dropped from the convoy. They\'ll come in handy.'],
    L17s: ['spk.arda', 'Olta ipleri her yerde. Ayağıma dolandı!', 'Fishing lines everywhere. One\'s wrapped round my foot!'],
    L17m: ['spk.arda', 'İpi salla, kes. Çekme, seni sürükler.', 'Wiggle it, cut it. Don\'t pull, it\'ll drag you.'],
    L18s: ['spk.kaan', 'Dur! Yaklaşma! Sen... enfekte misin?', 'Stop! Don\'t come closer! Are you... infected?'],
    L18m: ['spk.arda', 'Enfekte değilim! Dinle beni, abi!', 'I\'m not infected! Listen to me, bro!'],
    L19s: ['spk.arda', 'İki taraftan geliyorlar. Köprü kapanıyor!', 'They\'re coming from both ends. The bridge is closing in!'],
    L19m: ['spk.arda', 'Adam hâlâ bana bakıyor. Kim olduğunu bilmiyorum.', 'The guy\'s still watching me. I don\'t know who he is.'],
    L20s: ['spk.arda', 'Köprünün sonunda bir olta. Koca bir balıkçı.', 'At the end of the bridge, a rod. A huge fisherman.'],
    L20m: ['spk.arda', 'Olta atıyor, çekiyor. Dikkat, ağ atıyor!', 'He\'s casting and reeling. Careful, he\'s throwing a net!'],
  };
}

// Hood pools for levels 21-100 (four contextual pops per hood, used for start and mid; stage 5 uses the boss pop).
function poolLines() {
  return {
    H05p1: ['spk.kaan', 'Baharat çuvalları burnumu yakıyor. Ama ne güzel kokuyor!', 'The spice sacks burn my nose. But they smell so good!'],
    H05p2: ['spk.arda', 'Biber bulutu! Gözünü kapat, hemen geçer.', 'Pepper cloud! Shut your eyes, it passes fast.'],
    H05p3: ['spk.kaan', 'Hapşuruk... Hapşurdum, herhalde öldüm.', 'Ah-choo... I sneezed, so I must be dead.'],
    H05p4: ['spk.arda', 'İskele eğiliyor! Suya kaymadan geçelim.', 'The pier\'s tilting! Let\'s cross before we slide into the water.'],
    H06p1: ['spk.arda', 'Turnikeler kapalı. Öbür kapıya dolanalım.', 'Turnstiles shut. Let\'s go round to the other gate.'],
    H06p2: ['spk.kaan', 'Bagaj arabası! Kapıya sürelim, zombiler geçemez.', 'A luggage cart! Push it at the gate, zombies can\'t get through.'],
    H06p3: ['spk.arda', 'Saat durmuş. Ya da bize durmuş gibi geliyor.', 'The clock\'s stopped. Or it feels like it has.'],
    H06p4: ['spk.kaan', 'Sıraya girmişler. Bilet mi bekliyorlar acaba?', 'They\'ve formed a queue. Waiting for tickets, I wonder?'],
    H07p1: ['spk.arda', 'Kepenkler kapanıyor! Arkamda biri kapandı!', 'Shutters are coming down! One just closed behind me!'],
    H07p2: ['spk.kaan', 'Kilim rulosu iyi siper olur. Arkana saklan.', 'A rolled kilim makes good cover. Get behind it.'],
    H07p3: ['spk.arda', 'Tezgâhların arkasında bir şey kıpırdıyor.', 'Something\'s moving behind the counters.'],
    H07p4: ['spk.kaan', 'Gözünü ayırma. Bu labirentte kolay kaybolursun.', 'Don\'t take your eyes off it. This maze is easy to get lost in.'],
    H08p1: ['spk.arda', 'Güvercinler yine kalktı. Bir sürü geliyor.', 'The pigeons took off again. A lot of them are coming.'],
    H08p2: ['spk.kaan', 'Kitapçının kapısı aralık. Kim bıraktı ki?', 'The bookstall\'s door is ajar. Who left it like that?'],
    H08p3: ['spk.arda', 'Burada iyi okumuş biri yaşıyormuş. Kitap kokusu var.', 'Someone who read a lot lived here. The smell of books.'],
    H08p4: ['spk.kaan', 'Güvercinleri ürkütme. Bizi onlar uyarıyor.', 'Don\'t spook the pigeons. They\'re warning us.'],
    H09p1: ['spk.kaan', 'Vitrin ışığı çok sert. Göz gözü görmüyor.', 'The window light is harsh. You can\'t see a thing.'],
    H09p2: ['spk.arda', 'Üç metreden yakın geçersen uyanıyorlar. Mesafe!', 'They wake up if you pass within three metres. Keep your distance!'],
    H09p3: ['spk.kaan', 'Kumaş balyalarının arkasına saklanıyorlar.', 'They hide behind the fabric rolls.'],
    H09p4: ['spk.arda', 'Hepsi bana bakıyor gibi. Sanki bekliyorlar.', 'They all seem to be watching me. As if they\'re waiting.'],
    H10p1: ['spk.arda', 'Dolmuşların farları hâlâ yanıyor. Şerit gibi.', 'The minibus headlights are still on. Like lane markers.'],
    H10p2: ['spk.kaan', 'Açık kapılı dolmuşa binme. İçinde kim var, bilmiyoruz.', 'Don\'t get on an open minibus. We don\'t know who\'s inside.'],
    H10p3: ['spk.arda', 'Pide fırınının önünden geçiyoruz. Sıcak ekmek kokusu.', 'We\'re passing the pide bakery. The smell of hot bread.'],
    H10p4: ['spk.kaan', 'Ekmek kokusu... Usta\'nın ocağı gibi. Bir tane de bana.', 'Bread smell... like Usta\'s grill. One for me too.'],
    H11p1: ['spk.kaan', 'Buzdaki sandıklar gaz çıkarırsa zincirleme patlar.', 'If the crates on the ice release gas, they\'ll blow in a chain.'],
    H11p2: ['spk.arda', 'Buz eridi, zemin kaygan. Dikkat et.', 'The ice melted, the ground\'s slippery. Watch your step.'],
    H11p3: ['spk.kaan', 'Müzik hâlâ çalıyor. Şu sesi kesmemiz lazım.', 'The music\'s still playing. We have to cut that sound off.'],
    H11p4: ['spk.arda', 'Deniz kokuyor. Yolun yarısını geçmiş olabiliriz.', 'It smells of the sea. We may be halfway there.'],
    H12p1: ['spk.arda', 'Fenerin ışığı altı metre. Ötesi zifiri karanlık.', 'The torch reaches six metres. Beyond that, pitch black.'],
    H12p2: ['spk.kaan', 'Merdivenlerde sıra sıra dizilmişler. Basamakları tut.', 'They\'re lined up on the stairs. Hold the steps.'],
    H12p3: ['spk.arda', 'Telefon titredi. Bir çubuk... sonra hiç.', 'The phone buzzed. One bar... then none.'],
    H12p4: ['spk.kaan', 'Tünelde sesler yankılanıyor. Sessiz ol.', 'Sounds echo down the tunnel. Keep quiet.'],
    H13p1: ['spk.arda', 'Battaniyelerin üstünde yarım kalmış bir piknik.', 'A picnic left half-finished on the blankets.'],
    H13p2: ['spk.kaan', 'Denize itince sürükleniyorlar. Hiç hoş değil ama.', 'Shove them into the sea and they drift off. Not nice, but...'],
    H13p3: ['spk.arda', 'Bir kedi tıslıyor. Bir şey var demek.', 'A cat\'s hissing. That means something\'s there.'],
    H13p4: ['spk.kaan', 'Mangal dumanı. Biri hâlâ ateş yakıyor.', 'Grill smoke. Someone\'s still lighting a fire.'],
    H14p1: ['spk.arda', 'Surun üstünde yürüyoruz. Dar ama sağlam.', 'We\'re walking the top of the wall. Narrow, but solid.'],
    H14p2: ['spk.kaan', 'Üç anahtar bulalım, kapıyı açalım.', 'Let\'s find three keys and open the gate.'],
    H14p3: ['spk.arda', 'Bahçede çay masaları yolu kesiyor.', 'Tea tables in the garden are blocking the path.'],
    H14p4: ['spk.kaan', 'Sarmaşıkların arkasında bir şey hışırdıyor.', 'Something\'s rustling behind the ivy.'],
    H15p1: ['spk.arda', 'Bir bidon patlarsa hepsi zincirleme patlıyor.', 'If one drum blows, the whole row goes up in a chain.'],
    H15p2: ['spk.kaan', 'Konveyör beni itiyor! Kenara çekil!', 'The conveyor\'s pushing me! Get out of the way!'],
    H15p3: ['spk.arda', 'Boyanın kokusu başımı döndürüyor.', 'The paint fumes are making my head spin.'],
    H15p4: ['spk.kaan', 'Kimse vardiyanın bittiğini söylemiyor. Bitirelim.', 'Nobody\'s saying the shift is over. Let\'s finish it.'],
    H16p1: ['spk.kaan', 'Fıskiyeler zemini ıslattı. Hortumcu gelince dikkat.', 'The sprinklers soaked the ground. Watch out when the hose man comes.'],
    H16p2: ['spk.arda', 'Islak zeminde elektrik sıçrıyor. Bekle.', 'Electricity jumps across wet ground. Wait for it.'],
    H16p3: ['spk.kaan', 'Koşucular paket halinde geliyor. Yan yana dur.', 'Runners come in packs. Stand side by side.'],
    H16p4: ['spk.arda', 'Dizlerim sızlıyor ama deniz havası iyi geliyor.', 'My knees ache, but the sea air helps.'],
    H17p1: ['spk.kaan', 'Yürüyen merdiven durmuş. Artık tek yönlü rampa.', 'The escalator\'s stopped. It\'s a one-way ramp now.'],
    H17p2: ['spk.arda', 'Okul zili çalıyor. Her çalışta bir dalga geliyor.', 'The school bell\'s ringing. Every chime brings a wave.'],
    H17p3: ['spk.kaan', 'Dolapların arasında bir ayakkabı... ve bir defter.', 'A shoe between the lockers... and a notebook.'],
    H17p4: ['spk.arda', 'Burası her sabah kalabalıktı. Ben de buradaydım.', 'This place was packed every morning. I was here too.'],
    H18p1: ['spk.kaan', 'Dondurma arabası. Zil çalınca hemen kaç.', 'The ice-cream cart. When the bell rings, run.'],
    H18p2: ['spk.arda', 'Bisiklet yolundan geliyorlar. Ters yönden!', 'They\'re coming down the bike lane. The wrong way!'],
    H18p3: ['spk.kaan', 'Sahilde artık kimse yüzmüyor.', 'Nobody swims at the shore any more.'],
    H18p4: ['spk.arda', 'Çocukluğumun sahili. Aynı ama sessiz.', 'The shore of my childhood. The same, but silent.'],
    H19p1: ['spk.kaan', 'Pontonlar sallanıyor. Dengeni koru.', 'The pontoons are swaying. Keep your balance.'],
    H19p2: ['spk.arda', 'Halatlar ağ gibi. Zombiler takılıp kalıyor.', 'The ropes are like nets. Zombies are getting stuck.'],
    H19p3: ['spk.kaan', 'Denizciler çıkıyor. Hepsi uyandı mı acaba?', 'The sailors are crawling out. Are they all awake?'],
    H19p4: ['spk.arda', 'Eve bir kilometre. Sen de gel.', 'One kilometre to home. Come along.'],
    H20p1: ['spk.kaan', 'Ahmet Abi\'nin ekmek sepeti... Kalkan olabilir belki.', 'Ahmet Abi\'s bread basket... maybe it could be a shield.'],
    H20p2: ['spk.arda', 'Kapıcı kulübesinin anahtarı nerede olabilir?', 'Where might the porter\'s booth key be?'],
    H20p3: ['spk.kaan', 'Çamaşır ipleri arasında biri zıplıyor.', 'Someone\'s jumping between the laundry lines.'],
    H20p4: ['spk.arda', 'Apartmanın kapısı açık. İçeriden bir ses geliyor.', 'The building door is open. A sound from inside.'],
  };
}

// Mom's calls (P.Comic.call). Bars drop or recover per line; a last line at 0 bars ends in "Sinyal yok".
function callLines() {
  return {
    C05a: ['spk.anne', 'Arda! Yürüyor musun? Beni duyuyor musun?', 'Arda! Are you walking? Can you hear me?'],
    C05b: ['spk.arda', 'Duyuyorum anne! Tünel\'i geçtim, Ataköy\'e yürüyorum.', 'I can hear you! Passed Tünel, walking to Ataköy.'],
    C05c: ['spk.anne', 'Anayollardan uzak dur oğlum, tamam mı?', 'Stay off the main roads, son, okay?'],
    C05d: ['spk.arda', 'Tamam anne. Sen nerdesin?', 'Okay, Mom. Where are you?'],
    C05e: ['spk.anne', 'Dede\'nin... evine... [cızırtı] ...Sarıyer...', 'Dede\'s... house... [static] ...Sarıyer...'],
    C15a: ['spk.anne', 'Arda, seni zor duyuyorum... Ses çok...', 'Arda, I can barely hear you... The signal is...'],
    C15b: ['spk.arda', 'Anne! Yavaş konuş, kesiliyor!', 'Mom! Talk slower, you\'re cutting out!'],
    C15c: ['spk.anne', '...Baban... [cızırtı] ...kuzey... [cızırtı]...', '...your dad... [static] ...north... [static]...'],
    C15d: ['spk.arda', 'Kuzey mi? Anne? ...Anne!', 'North? Mom? ...Mom!'],
    C30a: ['spk.anne', 'Arda, bu son arama olabilir. Hat gidiyor, dinle!', 'Arda, this might be the last call. The line\'s going, listen!'],
    C30b: ['spk.arda', 'Anne, neredesin? Sesin çok net!', 'Mom, where are you? Your voice is so clear!'],
    C30c: ['spk.anne', 'Sarıyer\'deyiz, Dede\'nin evinde. Gel oğlum, dikkatli ol.', 'We\'re in Sarıyer, at Dede\'s. Come, son, but be careful.'],
    C30d: ['spk.arda', 'Geliyorum anne. Sen de bekle.', 'I\'m coming, Mom. You wait too.'],
    C30e: ['spk.anne', 'Seni seviyoruz. Eve gel oğlum... [cızırtı]', 'We love you. Come home, son... [static]'],
    C50a: ['spk.anne', '...Arda? Beni... [cızırtı] ...duyuyor musun?', '...Arda? Can you... [static] ...hear me?'],
    C50b: ['spk.arda', 'Anne! Bir kelime söyle, yeter!', 'Mom! Just say one word, that\'s enough!'],
    C50c: ['spk.anne', '...Ahmet... Abi... [cızırtı] ...ekmek...', '...Ahmet... Abi... [static] ...bread...'],
    C50d: ['spk.arda', 'Ahmet Abi mi? Anne? ...Anne!', 'Ahmet Abi? Mom? ...Mom!'],
    C70a: ['spk.arda', 'Anne! Bağlandı! Seni duyuyorum!', 'Mom! It\'s connected! I can hear you!'],
    C70b: ['spk.anne', 'Ahmet Abi\'ye selam söyle. Her sabah ekmek getirirdi, hatırla.', 'Say hello to Ahmet Abi. He brought bread every morning, remember.'],
    C70c: ['spk.arda', 'Hatırlıyorum anne. Sen iyi misin?', 'I remember, Mom. Are you okay?'],
    C70d: ['spk.anne', 'İyiyiz. Dede\'nin evi... Baban hep seni düşünüyor.', 'We\'re fine. Dede\'s place... Dad thinks of you all the time.'],
    C70e: ['spk.arda', 'Yakınım anne. Bekle beni.', 'I\'m close, Mom. Wait for me.'],
    C90a: ['spk.anne', 'Ataköy\'desin, değil mi? Sesin çok net geliyor!', 'You\'re in Ataköy, aren\'t you? Your voice is so clear!'],
    C90b: ['spk.arda', 'Marinanın yanındayım anne. Son kilometre.', 'I\'m by the marina, Mom. Last kilometre.'],
    C90c: ['spk.anne', 'Eve git oğlum. Biz de seni bekliyoruz.', 'Go home, son. We\'re waiting for you too.'],
    C90d: ['spk.arda', 'Geliyorum anne. Yarın sabah kapındayım.', 'I\'m coming, Mom. I\'ll be at your door tomorrow morning.'],
    C90e: ['spk.anne', 'Seni seviyoruz. Her şey yoluna girecek.', 'We love you. Everything will be all right.'],
  };
}

// Story page lines: L1 outro (O1), L5 cliffhanger (E5), Kaan joins (K20), Sirkeci slice end (E30),
// campfire (CMP), finale (FN). Letter lines use the baba speaker key (the letter is Dad's).
function pageLines() {
  return {
    E5a: ['spk.cap', 'Tramvay yan yattı. Vatman\'ın kulübesi sessiz.', 'The tram tipped over. The Vatman\'s cab has gone quiet.'],
    E5b: ['spk.news', '...kuzeydeki ormanda... [cızırtı] ...güvenli bölge...', '...in the forest up north... [static] ...safe zone...'],
    E5c: ['spk.arda', 'Kuzey mi? Ben eve gidiyorum.', 'North? I\'m going home.'],
    K20a: ['spk.cap', 'Koca Balıkçı yere devrildi. Köprüde kimse konuşmuyor.', 'The Big Fisherman is down. Nobody on the bridge is talking.'],
    K20b: ['spk.kaan', 'Adın Arda, değil mi? Ben Kaan. Sen gerçekten insan mısın?', 'Your name\'s Arda, right? I\'m Kaan. Are you really human?'],
    K20c: ['spk.arda', 'İnsanım abi. Gel, birlikte yürüyelim.', 'I\'m human, bro. Come on, let\'s walk together.'],
    K20d: ['spk.cap', 'Eminönü bu tarafta. İkisi birlikte yürüyor.', 'Eminönü is that way. The two of them walk on together.'],
    E30a: ['spk.cap', 'Sirkeci\'nin saati durdu. Son net aramadan beri.', 'The Sirkeci clock stopped. Since the last clear call.'],
    E30b: ['spk.arda', 'Anne? Beni duyuyor musun? ...Yok.', 'Mom? Can you hear me? ...No.'],
    E30c: ['spk.arda', 'Yürüyorum anne. Yürüyorum.', 'I\'m walking, Mom. I\'m walking.'],
    E30d: ['spk.cap', 'Ataköy: 12 km.', 'Ataköy: 12 km.'],
    CMPa: ['spk.cap', 'Kapalı bir fırın. Ocakta son bir ateş. Bizden başka kimse yok.', 'A closed bakery. One last fire in the oven. Nobody here but us.'],
    CMPb: ['spk.arda', 'Kaan... Mila\'ya âşık olduğumu biliyorsun, değil mi?', 'Kaan... you know I\'m in love with Mila, right?'],
    CMPc: ['spk.kaan', 'Herkes biliyor be. Sen de bunu kendine itiraf ettin, o kadar.', 'Everyone knows, man. You just admitted it to yourself, that\'s all.'],
    CMPd: ['spk.cap', 'Kaan bir süre sustu. Sonra ateşe bir odun attı.', 'Kaan went quiet for a while. Then he threw a log on the fire.'],
    CMPe: ['spk.cap', 'Yarın yine yürüyeceğiz.', 'Tomorrow we walk again.'],
    FNa: ['spk.cap', 'Ataköy. On yedi kilometre bitti.', 'Ataköy. Seventeen kilometres done.'],
    FNa2: ['spk.cap', 'Ev boş. Mutfakta iki bardak, kurumuş.', 'The flat is empty. Two cups in the kitchen, dried out.'],
    FNb: ['spk.arda', 'Anne? ...Baba?', 'Mom? ...Dad?'],
    FNl1: ['spk.baba', 'Oğlum, Anne ve Dede Sarıyer\'de, Dede\'nin evinde.', 'Son, Mom and Dede are in Sarıyer, at Dede\'s place.'],
    FNl2: ['spk.baba', 'Otoyollardan uzak dur. Radyo kuzeydeki orman için ne derse desin, oradan uzak dur.', 'Avoid the highways. Whatever the radio says about the northern forest, stay away.'],
    FNl3: ['spk.baba', 'Seni seviyorum. Baban.', 'Love you. Dad.'],
    FNc: ['spk.cap', 'Kapı çalındı.', 'Someone knocks on the door.'],
    FNd: ['spk.arda', 'Kim o?!', 'Who\'s there?!'],
    FNe: ['spk.cap', 'Mila.', 'Mila.'],
  };
}
  Object.assign(P.LINES, bossLines(), levelLines(), poolLines(), callLines(), pageLines());
})();
